from functools import lru_cache
from itertools import combinations
import random

def norm(fs):
 fs=set(fs)
 return tuple(sorted(f for f in fs if not any(f!=g and f&g==f for g in fs)))
@lru_cache(maxsize=300000)
def kd(fs,k):
 if len(fs)==1:return True
 m=fs[0].bit_count()
 if any(f.bit_count()!=m for f in fs):return False
 ss=set()
 for f in fs:
  bits=[1<<i for i in range(f.bit_length()) if f>>i&1]
  for s in range(1,min(k+1,m)+1):
   for c in combinations(bits,s):ss.add(sum(c))
 for s in sorted(ss,key=lambda x:(x.bit_count(),x)):
  dels=norm([f for f in fs if f&s!=s]+[f^v for f in fs if f&s==s for v in [1<<i for i in range(s.bit_length()) if s>>i&1]])
  if any(f.bit_count()!=m for f in dels):continue
  link=norm([f^s for f in fs if f&s==s])
  if kd(dels,k) and kd(link,k):return True
 return False

def skel(fs):
 return norm([f^u for f in fs for u in [1<<i for i in range(f.bit_length()) if f>>i&1]])
def admissible(fs,f,d):
 return all(x.bit_count()==d for x in norm([g&f for g in fs]))
if __name__=='__main__':
 for n,d in [(7,2),(8,2),(8,3),(9,3)]:
  allfs=[sum(1<<v for v in c) for c in combinations(range(n),d+1)]
  found=False
  for trial in range(500):
   fs=(random.choice(allfs),)
   while len(fs)<len(allfs):
    rem=[f for f in allfs if f not in fs and admissible(fs,f,d)]
    if not rem:
     print('STUCK SHELLING!',n,d,fs,flush=True);break
    fs=tuple(sorted(fs+(random.choice(rem),)))
    if d==2 and not kd(fs,0):
     print('NONVD',n,d,fs, 'edge',kd(fs,1),flush=True);found=True;break
    if d==3 and not kd(skel(fs),0):
     print('SKEL NONVD',n,d,fs,flush=True);found=True;break
   if found:break
  print('DONE',n,d,trial, kd.cache_info(),flush=True)

