{"content":"from functools import lru_cache
from itertools import combinations

# Faces and facets are represented by bit masks.  A tuple of facets is sorted.
def bits(x):
    while x:
        a=x&-x
        yield a
        x-=a

def canonical(fs):
    fs=set(fs)
    return tuple(sorted(f for f in fs if not any(f!=g and f&g==f for g in fs)))

def vertices(fs):
    ans=0
    for f in fs: ans |= f
    return ans

def subs(x,r):
    return [sum(c) for c in combinations(list(bits(x)),r)]

@lru_cache(None)
def certificate(fs,k):
    if len(fs)==1: return ('simplex',)
    if not fs: return None
    m=fs[0].bit_count()
    if any(f.bit_count()!=m for f in fs): return None
    candidates=set()
    for f in fs:
        for r in range(1,min(k+1,m)+1):
            candidates.update(subs(f,r))
    for s in sorted(candidates,key=lambda s:(s.bit_count(),s)):
        D=canonical([f for f in fs if f&s!=s]+
                    [f^v for f in fs if f&s==s for v in bits(s)])
        if any(f.bit_count()!=m for f in D): continue
        L=canonical(f^s for f in fs if f&s==s)
        if certificate(D,k) is not None and certificate(L,k) is not None:
            return (s,D,L)
    return None

@lru_cache(None)
def prefixes(fs,k):
    c=certificate(fs,k)
    assert c is not None
    if c[0]=='simplex': return fs
    s,D,L=c
    ans=prefixes(D,k)+tuple(s|f for f in prefixes(L,k))
    assert set(ans)==set(fs)
    return ans

@lru_cache(None)
def shellable(fs):
    if len(fs)==1: return True
    m=fs[0].bit_count()
    for f in fs:
        rest=tuple(g for g in fs if g!=f)
        trace=canonical(g&f for g in rest)
        if all(h.bit_count()==m-1 for h in trace) and shellable(rest):
            return True
    return False

def completion(fs,k):
    # Explicit construction using dimension-1 new vertices, dimension >=1.
    assert certificate(fs,k) is not None
    m=fs[0].bit_count()
    V=vertices(fs)
    if m<=2:
        return (),tuple(f for f in subs(V,m) if f not in fs)
    apex=1<<V.bit_length()
    L=canonical(f^v for f in fs for v in bits(f))
    order=[apex|g for g in prefixes(L,k)]
    B,linkorder=completion(L,k)
    order.extend(apex|g for g in linkorder)
    W=V
    for b in B: W |= b
    order.extend(f for f in subs(W,m) if f not in fs)
    # Recursion could use the already allocated apex, so rename its buffers.
    # The recursive ground set was V.  Its first new vertex is apex.
    # Move every recursive buffer up one position, leaving V unchanged.
    rename={b:b<<1 for b in B}
    if B:
        order=[sum(rename.get(b,b) if b!=apex else b for b in bits(f)) for f in []] # unused; rebuilt below
        def lift(g): return sum(rename.get(b,b) for b in bits(g))
        order=[apex|g for g in prefixes(L,k)]
        order.extend(apex|lift(g) for g in linkorder)
        W=V
        for b in B: W|=rename[b]
        order.extend(f for f in subs(W,m) if f not in fs)
    return (apex,)+tuple(rename[b] for b in B),tuple(order)

def verify_completion(fs,k):
    A,order=completion(fs,k)
    assert len(A)==max(0,fs[0].bit_count()-2)
    current=fs
    for f in order:
        assert f not in current
        current=tuple(sorted(current+(f,)))
        assert certificate(current,k) is not None
    W=vertices(fs)
    for a in A: W|=a
    assert set(current)==set(subs(W,fs[0].bit_count()))
    return len(A),len(order)

if __name__=='__main__':
    # This is a shellable, edge-decomposable, non-vertex-decomposable example.
    E=(14,19,25,37,41,44,49,52,67,74,76,97,98,112,137,138,145,146,148,161,164,168,176,196)
    assert certificate(E,0) is None
    assert certificate(E,1) is not None
    assert shellable(E)
    print('2-dimensional example, new vertices and added facets:',verify_completion(E,1),flush=True)
    # Cone preserves decomposability; also test the construction in dimension 3.
    cone=tuple(f|256 for f in E)
    print('3-dimensional example, new vertices and added facets:',verify_completion(cone,1),flush=True)
    for n,m in [(5,3),(6,4)]:
        U=tuple(subs((1<<n)-1,m)); size=1<<len(U)
        good=[False]*size
        good[-1]=True
        count=0
        for mask in range(size-1,0,-1):
            fs=tuple(U[i] for i in range(len(U)) if mask>>i&1)
            dec=certificate(fs,m-1) is not None
            assert dec==shellable(fs)
            if dec:
                count+=1
                if mask!=size-1:
                    good[mask]=any(good[mask|(1<<i)] for i in range(len(U)) if not mask>>i&1)
                assert good[mask]
        print('Exhaustive shellability equivalence and completion:',n,m,'complexes',size-1,'shellable',count,flush=True)
"}

