import itertools,time
import z3
n=8;m=4
sets=lambda r:[sum(1<<i for i in c) for c in itertools.combinations(range(n),r)]
F=sets(m);T=sets(3);E=sets(2)
y={f:z3.Bool('f'+str(f)) for f in F}
t={a:z3.Or([y[f] for f in F if f&a==a]) for a in T}
e={a:z3.Or([y[f] for f in F if f&a==a]) for a in E}
o={f:z3.Int('o'+str(f)) for f in F}
s=z3.Solver();s.set(timeout=240000)
s.add(y[F[0]],o[F[0]]==0,z3.Or([z3.Not(v) for v in y.values()]))
for f in F:
 s.add(o[f]>=0,o[f]<len(F))
 if f!=F[0]: s.add(z3.Implies(y[f],o[f]>0))
s.add(z3.Distinct(list(o.values())))
for v in range(n): s.add(z3.Or([y[f] for f in F if f>>v&1]))
for f in F:
 block=[]
 for a in E:
  if a&f==a:
   block.append(z3.And(e[a],*[z3.Not(t[b]) for b in T if b&f==b and b&a==a]))
 for v in range(n):
  if f>>v&1:
   block.append(z3.And(*[z3.Not(t[b]) for b in T if b&f==b and b>>v&1]))
 s.add(z3.Implies(z3.Not(y[f]),z3.Or(block)))
 for g in F:
  if f==g or (f&g).bit_count()==3:continue
  h=f&g
  cover=[z3.And(y[p],o[p]<o[f]) for p in F if (p&f).bit_count()==3 and p&h==h]
  s.add(z3.Implies(z3.And(y[f],y[g],o[g]<o[f]),z3.Or(cover)))
print('built',len(s.assertions()),flush=True)
a=s.check();print(a,flush=True)
if a==z3.sat:
 model=s.model();fs=sorted([f for f in F if z3.is_true(model.eval(y[f]))],key=lambda f:model.eval(o[f]).as_long())
 print('SHELLABLE TRAP',fs)

