        solver.add(y[f]==z3.And(ts),z3.Sum([z3.If(a,1,0) for a in ts])!=3)
        solver.add(o[f]>=0,o[f]<len(U))
    for a in triangles:
        solver.add(t[a]==z3.Or([y[f] for f in U if f&a==a]))
    for e in sub((1<<n)-1,2):solver.add(z3.Or([y[f] for f in U if f&e==e]))
    solver.add(y[U[0]],y[U[1]],o[U[0]]==0,o[U[1]]==1)
    solver.add(z3.Or([z3.Not(y[f]) for f in U]))
    for f in U:
